cd /app; cat > sched.py <<'EOF'
def run(env):
    obs = []
    phase2 = False
    for i in range(env.n_segments):
        if not phase2:
            b = 128 if i % 2 == 0 else 256
        else:
            b = 1024 if i % 2 == 0 else 2048
        r = env.run_segment(b)
        obs.append((i, b, round(r["steps"], 5)))
        if r["steps"] > 0.1:
            phase2 = True
    raise RuntimeError("OBS to=%r thr=%r " % (env.t_overhead, env.throughput) + repr(obs))
EOF
bin/lab evaluate
